import numpy as npimport pandas as pdimport matplotlib.pyplot as pltfrom sklearn.model_selection import train_test_splitfrom sklearn.preprocessing import StandardScalerfrom sklearn.preprocessing import LabelEncoderfrom sklearn.svm import SVCfrom matplotlib.colors import ListedColormapfrom sklearn.metrics import accuracy_scorefrom sklearn.model_selection import GridSearchCVfrom tqdm import tqdmfrom math import factorialimport randomfrom itertools import combinationsfrom sklearn.linear_model import LogisticRegressionout_df= pd.DataFrame()for clusterx in (range(0,26)):    if clusterx in [21] :        continue        # read in     base_path = "/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/degs_0.1_f_m//cluster_"    path = f"{base_path}{clusterx}.csv"    cluster_data = pd.read_csv(path)        # set up training data    training_data = cluster_data[cluster_data['Status'].isin(['M','F'])]    training_labels = np.where(training_data['Status']=='M', 0, 1)    training_matrix = training_data.iloc[:,3:].to_numpy()    #set up test data    test_data = cluster_data[cluster_data['Status'].isin(['D', 'E', 'NF'])] # include expandeds and new female    test_matrix = test_data.iloc[:,3:].to_numpy()        # scale data    scaler = StandardScaler()    scaler.fit(training_matrix)    train_std_x = scaler.transform(training_matrix)    test_std_x = scaler.transform(test_matrix)            #initialize model    log = LogisticRegression(C=10, solver ='lbfgs')        #fit    log.fit(train_std_x, training_labels)    predictions = log.predict_proba(test_std_x)[:,1]    binary = log.predict(test_std_x)            n_degs = training_matrix.shape[1]        ind_predictions = pd.DataFrame({        'individual': test_data['individual'].values,        'status': test_data['Status'].values,        'prediction': predictions,        'binary':binary,        'cluster': clusterx,        'n_degs':n_degs    })                    out_df = pd.concat([out_df, ind_predictions])    out_df.to_csv("/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/logistic_individual_probabilities_07_05_2025.csv")out_df['prediction'].groupby(out_df['status']).agg('mean').reset_index()out_df['prediction'].groupby(out_df['cluster']).agg('mean').reset_index()plt.scatter(out_df['cluster'], out_df['prediction'])